"""API-level tests for the evidence conflict check (backend/conflict_check.py).

The router and the LLM client are both stubbed: the router returns a fixed
answer over two sources, and the fake client returns a canned value-extraction
reply. These pin the wiring -- status conflicting_evidence on disagreement,
unchanged status on agreement / failure / off, precedence of a withheld guard
result, and the audit field. Extraction and comparison rules are covered by
tests/test_conflict_check.py.
"""

import dataclasses
import json

import pytest
from fastapi.testclient import TestClient

from backend.app import app
from backend.app import runtime as app_module
from backend.audit import JsonlAuditSink

SOURCES = [
    {"filename": "SOP_2024.pdf", "content": "Mechanical labor is capped at $95 per hour.", "score": 1.0},
    {"filename": "SOP_2026.pdf", "content": "Mechanical labor is capped at $125 per hour.", "score": 0.9},
]
DISAGREE = json.dumps({"values": [{"source": "SOP_2024.pdf", "value": "$95 per hour"},
                                  {"source": "SOP_2026.pdf", "value": "$125 per hour"}]})
AGREE = json.dumps({"values": [{"source": "SOP_2024.pdf", "value": "$125 per hour"},
                               {"source": "SOP_2026.pdf", "value": "$125/hr"}]})


class _StubRouter:
    def __init__(self, answer):
        self.answer = answer

    def _result(self):
        return {"answer": self.answer, "sources": [dict(s) for s in SOURCES], "claim_dossier": None,
                "engine": "lm-studio (agentic)", "pipeline_logs": []}

    def run_query(self, **kwargs):
        return self._result()

    def run_query_stream(self, **kwargs):
        yield {"type": "chunk", "text": self.answer}
        yield {"type": "final", **self._result()}


class _FakeClient:
    def __init__(self, reply=None, error=None):
        self.reply, self.error, self.calls = reply, error, 0

    def model_for_stage(self, stage):
        return "fake-model"

    def complete(self, messages, *, model, temperature, max_tokens, stage="synthesis"):
        self.calls += 1
        if self.error:
            raise self.error
        return self.reply


@pytest.fixture
def conflict_app(tmp_path, monkeypatch):
    def _build(answer="The 2026 SOP caps mechanical labor at $125 per hour.", reply=DISAGREE,
               error=None, mode="llm", guard="withhold"):
        sink_path = tmp_path / "audit.jsonl"
        client = _FakeClient(reply, error)
        monkeypatch.setattr(app_module, "_audit_sink", JsonlAuditSink(sink_path))
        monkeypatch.setattr(app_module, "agentic_router", _StubRouter(answer))
        monkeypatch.setattr(app_module, "_llm_client", client)
        monkeypatch.setattr(app_module, "settings", dataclasses.replace(
            app_module.settings, conflict_check=mode, answer_guard_mode=guard))
        return TestClient(app), sink_path, client

    return _build


def _chat(client):
    response = client.post("/api/chat", json={"query": "What is the mechanical labor cap?", "engine": "simulated"})
    assert response.status_code == 200
    return response.json()

def build_messages(query: str, sources: Sequence[dict]) -> list[dict]:
    """Render the system prompt plus one escaped `<source file="...">` block per excerpt."""
    blocks = []
    for source in sources:
        filename = (source or {}).get("filename")
        if not filename:
            continue
        blocks.append(
            f'<source file="{_esc(filename)}">\n{_esc((source.get("content") or "")[:MAX_EXCERPT_CHARS])}\n</source>'
        )
        if len(blocks) == MAX_SOURCES:
            break
    user = "Question: " + query + "\n\nExcerpts:\n" + "\n\n".join(blocks)
    return [{"role": "system", "content": SYSTEM_PROMPT}, {"role": "user", "content": user}]


def parse_values(raw: str, allowed_sources: Collection[str]) -> tuple[SourceValue, ...] | None:
    """Parse the model's reply into validated entries, or None when it is not usable.

    An empty tuple is a valid parse (the model found no values) and is deliberately
    distinct from None (the reply was unparsable), because callers treat those differently.
    A reply that is not even text (a client that returns None, say) is unparsable, not a
    crash: `assess_conflict` promises never to raise.
    """
    if not isinstance(raw, str):
        return None
    text = _THINK_RE.sub("", raw).strip()
    if "```" in text:
        fenced = text.split("```")
        if len(fenced) > 1:
            text = fenced[1]

    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end < start:
        return None
    try:
        payload = json.loads(text[start : end + 1])
    except (ValueError, TypeError):
        return None
    if not isinstance(payload, dict) or not isinstance(payload.get("values"), list):
        return None

    parsed: list[SourceValue] = []
    seen: set[str] = set()
    for entry in payload["values"]:
        if not isinstance(entry, dict):
            continue
        source = entry.get("source")
        value = entry.get("value")
        if not isinstance(source, str) or not isinstance(value, str):
            continue
        source = source.strip()
        value = value.strip()
        if source not in allowed_sources or not value or source in seen:
            continue
        seen.add(source)
        parsed.append(SourceValue(source=source, value=value[:120]))
    return tuple(parsed)


def assess_conflict(
    llm_client, query: str, sources: Sequence[dict], *, model: str | None = None
) -> ConflictAssessment | None:
    """Ask the model for the per-source values, then decide disagreement in code.

    Returns None when there is nothing to compare (no client, fewer than two distinct
    sources) or when the model call or its reply is unusable. Never raises.
    """
    distinct = tuple(dict.fromkeys(source["filename"] for source in sources[:MAX_SOURCES] if source.get("filename")))
    if llm_client is None or len(distinct) < 2:
        return None

    model = model or llm_client.model_for_stage("conflict_check")
    try:
        raw = llm_client.complete(
            build_messages(query, sources),
            model=model,
            temperature=0,
            max_tokens=MAX_TOKENS,
            stage="conflict_check",
        )
    except Exception:
        return None

    values = parse_values(raw, distinct)
    if values is None:
        return None

    disagreement = values_disagree(values)
    summary = ""
    if disagreement:
        numeric = [value for value in values if numbers_in(value.value)]
        summary = "Sources disagree: " + "; ".join(f"{value.source} gives {value.value}" for value in numeric)
    return ConflictAssessment(disagreement=disagreement, values=values, summary=summary)
